sp_BreakdownFormaPagamento	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_BreakdownFormaPagamento`(\n\n    IN p_idEmpresa INT,\n\n    IN p_idCaixa   INT\n\n)\nBEGIN\n\n    SELECT\n\n        fp.idFormaPagamento,\n\n        fp.nome AS nomeFormaPagamento,\n\n        'PAGAMENTO' AS tipoAgrupamento,\n\n        SUM(CASE WHEN cf.tipo = 1 THEN lc.valor ELSE 0 END) AS totalEntradas,\n\n        SUM(CASE WHEN cf.tipo = 2 THEN lc.valor ELSE 0 END) AS totalSaidas,\n\n        SUM(CASE WHEN cf.tipo = 1 THEN lc.valor ELSE -lc.valor END) AS saldoLiquido\n\n    FROM LancamentoCaixa lc\n\n    JOIN FormaPagamento fp ON fp.idFormaPagamento = lc.idFormaPagamento\n\n    JOIN CategoriaFinanceira cf ON cf.idCategoriaFinanceira = lc.idCategoriaFinanceira\n\n    WHERE lc.idEmpresa = p_idEmpresa\n\n      AND lc.idCaixa = p_idCaixa\n\n      AND lc.tipoLancamento NOT IN ('SANGRIA', 'SUPRIMENTO')\n\n    GROUP BY fp.idFormaPagamento, fp.nome\n\n\n\n    UNION ALL\n\n\n\n    SELECT\n\n        0 AS idFormaPagamento,\n\n        'Movimentos Internos' AS nomeFormaPagamento,\n\n        'INTERNO' AS tipoAgrupamento,\n\n        SUM(CASE WHEN lc.tipoLancamento = 'SUPRIMENTO' THEN lc.valor ELSE 0 END) AS totalEntradas,\n\n        SUM(CASE WHEN lc.tipoLancamento = 'SANGRIA' THEN lc.valor ELSE 0 END) AS totalSaidas,\n\n        SUM(CASE WHEN lc.tipoLancamento = 'SUPRIMENTO' THEN lc.valor ELSE -lc.valor END) AS saldoLiquido\n\n    FROM LancamentoCaixa lc\n\n    WHERE lc.idEmpresa = p_idEmpresa\n\n      AND lc.idCaixa = p_idCaixa\n\n      AND lc.tipoLancamento IN ('SANGRIA', 'SUPRIMENTO')\n\n    HAVING totalEntradas > 0 OR totalSaidas > 0\n\n\n\n    ORDER BY tipoAgrupamento, nomeFormaPagamento;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
